-- Independent MD02 organization registry. Published V1-V16 remain byte-identical.
CREATE TABLE plugin_finance_counterparty_entity_guard(tenant_id uuid NOT NULL,legal_entity_id uuid NOT NULL,generation bigint NOT NULL DEFAULT 0 CHECK(generation>=0),PRIMARY KEY(tenant_id,legal_entity_id),FOREIGN KEY(tenant_id,legal_entity_id) REFERENCES plugin_finance_entity(tenant_id,id));
CREATE TABLE plugin_finance_counterparty_home_guard(tenant_id uuid NOT NULL,legal_entity_id uuid NOT NULL,book_id uuid NOT NULL,epoch uuid NOT NULL DEFAULT gen_random_uuid(),generation bigint NOT NULL DEFAULT 0 CHECK(generation>=0),PRIMARY KEY(tenant_id,legal_entity_id,book_id),FOREIGN KEY(tenant_id,legal_entity_id) REFERENCES plugin_finance_entity(tenant_id,id),FOREIGN KEY(tenant_id,book_id) REFERENCES plugin_finance_book(tenant_id,id));
INSERT INTO plugin_finance_counterparty_entity_guard SELECT tenant_id,id,0 FROM plugin_finance_entity;
INSERT INTO plugin_finance_counterparty_home_guard(tenant_id,legal_entity_id,book_id) SELECT tenant_id,legal_entity_id,id FROM plugin_finance_book;
CREATE FUNCTION plugin_finance_counterparty_new_scope() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_TABLE_NAME='plugin_finance_entity' THEN INSERT INTO plugin_finance_counterparty_entity_guard VALUES(NEW.tenant_id,NEW.id,0);ELSE INSERT INTO plugin_finance_counterparty_home_guard(tenant_id,legal_entity_id,book_id) VALUES(NEW.tenant_id,NEW.legal_entity_id,NEW.id);END IF;RETURN NEW;END $$;
CREATE TRIGGER finance_counterparty_new_entity AFTER INSERT ON plugin_finance_entity FOR EACH ROW EXECUTE FUNCTION plugin_finance_counterparty_new_scope();
CREATE TRIGGER finance_counterparty_new_book AFTER INSERT ON plugin_finance_book FOR EACH ROW EXECUTE FUNCTION plugin_finance_counterparty_new_scope();
CREATE TABLE plugin_finance_counterparty_registry(
 tenant_id uuid NOT NULL,legal_entity_id uuid NOT NULL,id uuid NOT NULL,home_book_id uuid NOT NULL,namespace text NOT NULL CHECK(namespace='ORGANIZATION_DECLARED_REGISTRATION'),jurisdiction text NOT NULL CHECK(jurisdiction~'^[A-Z]{2}$'),identifier text NOT NULL CHECK(identifier~'^[A-Z0-9._/-]{1,64}$'),operation_id uuid NOT NULL,initial_payload jsonb NOT NULL,initial_payload_hash text NOT NULL CHECK(initial_payload_hash~'^[a-f0-9]{64}$'),created_by jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,version bigint NOT NULL DEFAULT 0 CHECK(version>=0),latest_revision_id uuid,pending_revision_id uuid,approved_revision_id uuid,
 creator_account uuid GENERATED ALWAYS AS((created_by->>'accountId')::uuid) STORED,creator_person uuid GENERATED ALWAYS AS((created_by->>'personId')::uuid) STORED,creator_binding uuid GENERATED ALWAYS AS((created_by->>'bindingId')::uuid) STORED,
 PRIMARY KEY(tenant_id,legal_entity_id,id),UNIQUE(tenant_id,legal_entity_id,namespace,jurisdiction,identifier),UNIQUE(tenant_id,legal_entity_id,operation_id),UNIQUE(tenant_id,legal_entity_id,id,home_book_id),CHECK(creator_account IS NOT NULL AND creator_person IS NOT NULL AND creator_binding IS NOT NULL),FOREIGN KEY(tenant_id,legal_entity_id,home_book_id) REFERENCES plugin_finance_counterparty_home_guard(tenant_id,legal_entity_id,book_id),FOREIGN KEY(tenant_id,creator_binding,creator_account,creator_person) REFERENCES plugin_finance_person_binding(tenant_id,id,account_id,person_id));
CREATE TABLE plugin_finance_counterparty_revision(
 tenant_id uuid NOT NULL,legal_entity_id uuid NOT NULL,counterparty_id uuid NOT NULL,id uuid NOT NULL,revision_no bigint NOT NULL CHECK(revision_no>0),version bigint NOT NULL DEFAULT 1 CHECK(version IN(1,2)),status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','APPROVED','REJECTED','CANCELLED')),desired_status text NOT NULL CHECK(desired_status IN('ACTIVE','FROZEN','INACTIVE')),previous_revision_id uuid,base_approved_revision_id uuid,base_approved_digest text,content jsonb NOT NULL,content_digest text NOT NULL CHECK(content_digest~'^[a-f0-9]{64}$'),reason text NOT NULL CHECK(length(reason) BETWEEN 1 AND 1000),maker jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,decision_id uuid,
 maker_account uuid GENERATED ALWAYS AS((maker->>'accountId')::uuid) STORED,maker_person uuid GENERATED ALWAYS AS((maker->>'personId')::uuid) STORED,maker_binding uuid GENERATED ALWAYS AS((maker->>'bindingId')::uuid) STORED,
 PRIMARY KEY(tenant_id,legal_entity_id,id),UNIQUE(tenant_id,legal_entity_id,counterparty_id,id),UNIQUE(tenant_id,legal_entity_id,counterparty_id,revision_no),UNIQUE(tenant_id,legal_entity_id,id,content_digest),CHECK(maker_account IS NOT NULL AND maker_person IS NOT NULL AND maker_binding IS NOT NULL),CHECK((status='PENDING' AND version=1 AND decision_id IS NULL) OR(status<>'PENDING' AND version=2 AND decision_id IS NOT NULL)),CHECK((base_approved_revision_id IS NULL)=(base_approved_digest IS NULL)),FOREIGN KEY(tenant_id,legal_entity_id,counterparty_id) REFERENCES plugin_finance_counterparty_registry(tenant_id,legal_entity_id,id),FOREIGN KEY(tenant_id,legal_entity_id,counterparty_id,previous_revision_id) REFERENCES plugin_finance_counterparty_revision(tenant_id,legal_entity_id,counterparty_id,id),FOREIGN KEY(tenant_id,legal_entity_id,counterparty_id,base_approved_revision_id) REFERENCES plugin_finance_counterparty_revision(tenant_id,legal_entity_id,counterparty_id,id),FOREIGN KEY(tenant_id,maker_binding,maker_account,maker_person) REFERENCES plugin_finance_person_binding(tenant_id,id,account_id,person_id));
CREATE UNIQUE INDEX finance_counterparty_one_pending ON plugin_finance_counterparty_revision(tenant_id,legal_entity_id,counterparty_id) WHERE status='PENDING';
CREATE INDEX finance_counterparty_revision_page ON plugin_finance_counterparty_revision(tenant_id,legal_entity_id,counterparty_id,revision_no DESC,id);
CREATE INDEX finance_counterparty_home_page ON plugin_finance_counterparty_registry(tenant_id,legal_entity_id,home_book_id,created_at DESC,id DESC);
CREATE TABLE plugin_finance_counterparty_decision(
 tenant_id uuid NOT NULL,legal_entity_id uuid NOT NULL,counterparty_id uuid NOT NULL,revision_id uuid NOT NULL,id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('APPROVE','REJECT','CANCEL')),content_digest text NOT NULL,actor jsonb NOT NULL,reason text NOT NULL CHECK(length(reason) BETWEEN 1 AND 1000),created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
 actor_account uuid GENERATED ALWAYS AS((actor->>'accountId')::uuid) STORED,actor_person uuid GENERATED ALWAYS AS((actor->>'personId')::uuid) STORED,actor_binding uuid GENERATED ALWAYS AS((actor->>'bindingId')::uuid) STORED,
 PRIMARY KEY(tenant_id,legal_entity_id,id),UNIQUE(tenant_id,legal_entity_id,revision_id),UNIQUE(tenant_id,legal_entity_id,counterparty_id,revision_id,id),CHECK(actor_account IS NOT NULL AND actor_person IS NOT NULL AND actor_binding IS NOT NULL),FOREIGN KEY(tenant_id,legal_entity_id,counterparty_id,revision_id) REFERENCES plugin_finance_counterparty_revision(tenant_id,legal_entity_id,counterparty_id,id),FOREIGN KEY(tenant_id,legal_entity_id,revision_id,content_digest) REFERENCES plugin_finance_counterparty_revision(tenant_id,legal_entity_id,id,content_digest),FOREIGN KEY(tenant_id,actor_binding,actor_account,actor_person) REFERENCES plugin_finance_person_binding(tenant_id,id,account_id,person_id));
ALTER TABLE plugin_finance_counterparty_revision ADD FOREIGN KEY(tenant_id,legal_entity_id,counterparty_id,id,decision_id) REFERENCES plugin_finance_counterparty_decision(tenant_id,legal_entity_id,counterparty_id,revision_id,id) DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE plugin_finance_counterparty_registry ADD FOREIGN KEY(tenant_id,legal_entity_id,id,latest_revision_id) REFERENCES plugin_finance_counterparty_revision(tenant_id,legal_entity_id,counterparty_id,id) DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE plugin_finance_counterparty_registry ADD FOREIGN KEY(tenant_id,legal_entity_id,id,pending_revision_id) REFERENCES plugin_finance_counterparty_revision(tenant_id,legal_entity_id,counterparty_id,id) DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE plugin_finance_counterparty_registry ADD FOREIGN KEY(tenant_id,legal_entity_id,id,approved_revision_id) REFERENCES plugin_finance_counterparty_revision(tenant_id,legal_entity_id,counterparty_id,id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE plugin_finance_counterparty_request(actor_id uuid NOT NULL,request_key text NOT NULL CHECK(length(request_key) BETWEEN 1 AND 128),tenant_id uuid NOT NULL,legal_entity_id uuid NOT NULL,home_book_id uuid NOT NULL,route text NOT NULL,payload_hash text NOT NULL CHECK(payload_hash~'^[a-f0-9]{64}$'),counterparty_id uuid NOT NULL,revision_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(actor_id,request_key),FOREIGN KEY(tenant_id,legal_entity_id,counterparty_id,home_book_id) REFERENCES plugin_finance_counterparty_registry(tenant_id,legal_entity_id,id,home_book_id),FOREIGN KEY(tenant_id,legal_entity_id,counterparty_id,revision_id) REFERENCES plugin_finance_counterparty_revision(tenant_id,legal_entity_id,counterparty_id,id));
CREATE TABLE plugin_finance_counterparty_audit(tenant_id uuid NOT NULL,legal_entity_id uuid NOT NULL,counterparty_id uuid NOT NULL,revision_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),action text NOT NULL CHECK(action IN('PROPOSE','APPROVE','REJECT','CANCEL')),actor jsonb NOT NULL,reason text NOT NULL CHECK(length(reason) BETWEEN 1 AND 1000),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,legal_entity_id,id),UNIQUE(tenant_id,legal_entity_id,revision_id,action),FOREIGN KEY(tenant_id,legal_entity_id,counterparty_id,revision_id) REFERENCES plugin_finance_counterparty_revision(tenant_id,legal_entity_id,counterparty_id,id));
CREATE FUNCTION plugin_finance_counterparty_digest(v jsonb) RETURNS text LANGUAGE sql IMMUTABLE STRICT AS $$ SELECT encode(sha256(convert_to(v::text,'UTF8')),'hex') $$;
CREATE FUNCTION plugin_finance_counterparty_fields(v jsonb,ks text[]) RETURNS void LANGUAGE plpgsql IMMUTABLE AS $$ BEGIN IF jsonb_typeof(v) IS DISTINCT FROM 'object' OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(v) k) IS DISTINCT FROM(SELECT array_agg(k ORDER BY k) FROM unnest(ks) k) THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='INVALID_INPUT';END IF;END $$;
CREATE FUNCTION plugin_finance_counterparty_text(v jsonb,maxlen int,nullable boolean DEFAULT false) RETURNS text LANGUAGE plpgsql IMMUTABLE AS $$ DECLARE s text; BEGIN IF nullable AND v='null'::jsonb THEN RETURN NULL;END IF;IF jsonb_typeof(v) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='INVALID_INPUT';END IF;s=normalize(v#>>'{}',NFC);IF length(s)<1 OR length(s)>maxlen OR s~U&'[\0001-\0008\000B\000C\000E-\001F\007F-\009F]' OR translate(s,E' \t\r\n'||U&'\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000','')='' THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='INVALID_INPUT';END IF;RETURN s;END $$;
CREATE FUNCTION plugin_finance_counterparty_identity(v jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE AS $$ DECLARE j text;i text;BEGIN PERFORM plugin_finance_counterparty_fields(v,ARRAY['namespace','jurisdiction','identifier','verification']);IF v->>'namespace' IS DISTINCT FROM 'ORGANIZATION_DECLARED_REGISTRATION' OR v->>'verification' IS DISTINCT FROM 'ORGANIZATION_DECLARED_NOT_GOVERNMENT_VERIFIED' THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='INVALID_INPUT';END IF;j=plugin_finance_counterparty_text(v->'jurisdiction',64);i=plugin_finance_counterparty_text(v->'identifier',128);IF j~'[^ -~]' OR i~'[^ -~]' THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='INVALID_INPUT';END IF;j=translate(btrim(j,' '),'abcdefghijklmnopqrstuvwxyz','ABCDEFGHIJKLMNOPQRSTUVWXYZ');i=translate(btrim(i,' '),'abcdefghijklmnopqrstuvwxyz','ABCDEFGHIJKLMNOPQRSTUVWXYZ');IF j!~'^[A-Z]{2}$' OR i!~'^[A-Z0-9._/-]{1,64}$' THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='INVALID_INPUT';END IF;RETURN jsonb_build_object('namespace','ORGANIZATION_DECLARED_REGISTRATION','jurisdiction',j,'identifier',i,'verification','ORGANIZATION_DECLARED_NOT_GOVERNMENT_VERIFIED');END $$;
CREATE FUNCTION plugin_finance_counterparty_content(v jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE AS $$ DECLARE name text;terms text;contract text;basis text;registration text;relation text;roles jsonb; BEGIN PERFORM plugin_finance_counterparty_fields(v,ARRAY['displayName','roles','settlementTerms','contractDescription','relatedPartyStatus','relatedPartyBasis','registrationBasis']);name=plugin_finance_counterparty_text(v->'displayName',300);terms=plugin_finance_counterparty_text(v->'settlementTerms',1000,true);contract=plugin_finance_counterparty_text(v->'contractDescription',1000,true);basis=plugin_finance_counterparty_text(v->'relatedPartyBasis',1000,true);registration=plugin_finance_counterparty_text(v->'registrationBasis',1000);relation=plugin_finance_counterparty_text(v->'relatedPartyStatus',20);IF name~U&'[\0001-\001F\007F-\009F]' OR relation NOT IN('UNKNOWN','RELATED','NOT_RELATED') OR(relation='UNKNOWN')<>(basis IS NULL) OR jsonb_typeof(v->'roles') IS DISTINCT FROM 'array' OR jsonb_array_length(v->'roles') NOT BETWEEN 1 AND 2 THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='INVALID_INPUT';END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements(v->'roles') r WHERE jsonb_typeof(r) IS DISTINCT FROM 'string' OR r#>>'{}' NOT IN('CUSTOMER','SUPPLIER')) OR(SELECT count(DISTINCT r) FROM jsonb_array_elements(v->'roles') r)<>jsonb_array_length(v->'roles') THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='INVALID_INPUT';END IF;SELECT jsonb_agg(r ORDER BY r#>>'{}') INTO roles FROM jsonb_array_elements(v->'roles') r;RETURN jsonb_build_object('displayName',name,'roles',roles,'settlementTerms',terms,'contractDescription',contract,'relatedPartyStatus',relation,'relatedPartyBasis',basis,'registrationBasis',registration);END $$;
CREATE FUNCTION plugin_finance_counterparty_lock(t uuid,e uuid,b uuid) RETURNS void LANGUAGE plpgsql AS $$ BEGIN PERFORM tenant_id FROM plugin_finance_person_realm WHERE tenant_id=t FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_IDENTITY_UNAVAILABLE';END IF;PERFORM id FROM plugin_finance_book WHERE tenant_id=t AND id=b AND legal_entity_id=e FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SCOPE_DENIED';END IF;PERFORM legal_entity_id FROM plugin_finance_counterparty_entity_guard WHERE tenant_id=t AND legal_entity_id=e FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_OBSERVATION_UNAVAILABLE';END IF;END $$;
CREATE FUNCTION plugin_finance_counterparty_actor(t uuid,b uuid,who jsonb,roles text[]) RETURNS void LANGUAGE plpgsql AS $$ DECLARE actual jsonb;BEGIN BEGIN actual=plugin_finance_journal_person_identity(t,(who->>'accountId')::uuid,true);EXCEPTION WHEN raise_exception THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_IDENTITY_UNAVAILABLE';END;IF actual IS DISTINCT FROM who OR NOT EXISTS(SELECT 1 FROM plugin_finance_member WHERE tenant_id=t AND book_id=b AND user_id=(who->>'accountId')::uuid AND enabled AND role=ANY(roles)) THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SCOPE_DENIED';END IF;END $$;
CREATE FUNCTION plugin_finance_counterparty_revision_digest(t uuid,e uuid,p uuid,r uuid,n bigint,previous uuid,base uuid,base_digest text,desired text,content jsonb,reason text,maker jsonb) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT plugin_finance_counterparty_digest(jsonb_build_object('format','COUNTERPARTY_REVISION_PG_V1','tenantId',t,'legalEntityId',e,'counterpartyId',p,'revisionId',r,'revision',n::text,'previousRevisionId',previous,'baseApprovedRevisionId',base,'baseApprovedContentDigest',base_digest,'desiredStatus',desired,'content',content,'reason',reason,'maker',maker)) $$;
CREATE FUNCTION plugin_finance_counterparty_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE p plugin_finance_counterparty_registry;oldrev plugin_finance_counterparty_revision;base plugin_finance_counterparty_revision;r plugin_finance_counterparty_revision;who jsonb;ct jsonb;n jsonb;o jsonb;identity jsonb;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;
 n=to_jsonb(NEW);IF TG_OP='UPDATE' THEN o=to_jsonb(OLD);END IF;
 IF TG_TABLE_NAME IN('plugin_finance_counterparty_entity_guard','plugin_finance_counterparty_home_guard') THEN
  IF TG_OP='UPDATE' AND ((n-ARRAY['generation']) IS DISTINCT FROM(o-ARRAY['generation']) OR(n->>'generation')::bigint<>(o->>'generation')::bigint+1) THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;RETURN NEW;
 END IF;
 IF TG_TABLE_NAME='plugin_finance_counterparty_registry' THEN
  PERFORM plugin_finance_counterparty_lock(NEW.tenant_id,NEW.legal_entity_id,NEW.home_book_id);
  IF TG_OP='INSERT' THEN
   PERFORM plugin_finance_counterparty_actor(NEW.tenant_id,NEW.home_book_id,NEW.created_by,ARRAY['OWNER']);
   PERFORM plugin_finance_counterparty_fields(NEW.initial_payload,ARRAY['schemaVersion','operationId','reason','identity','content','organizationDeclarationConfirmed','identityNotPlaceholderConfirmed']);
   identity=plugin_finance_counterparty_identity(NEW.initial_payload->'identity');ct=plugin_finance_counterparty_content(NEW.initial_payload->'content');
   IF NEW.created_at IS DISTINCT FROM CURRENT_TIMESTAMP OR NEW.updated_at IS DISTINCT FROM CURRENT_TIMESTAMP OR NEW.version<>0 OR NEW.latest_revision_id IS NOT NULL OR NEW.pending_revision_id IS NOT NULL OR NEW.approved_revision_id IS NOT NULL OR NEW.initial_payload->>'schemaVersion' IS DISTINCT FROM 'counterparty/1' OR NEW.initial_payload->'organizationDeclarationConfirmed' IS DISTINCT FROM 'true'::jsonb OR NEW.initial_payload->'identityNotPlaceholderConfirmed' IS DISTINCT FROM 'true'::jsonb OR NEW.operation_id IS DISTINCT FROM(NEW.initial_payload->>'operationId')::uuid OR NEW.namespace IS DISTINCT FROM identity->>'namespace' OR NEW.jurisdiction IS DISTINCT FROM identity->>'jurisdiction' OR NEW.identifier IS DISTINCT FROM identity->>'identifier' OR NEW.initial_payload->'identity' IS DISTINCT FROM identity OR NEW.initial_payload->'content' IS DISTINCT FROM ct OR NEW.initial_payload_hash IS DISTINCT FROM plugin_finance_counterparty_digest(NEW.initial_payload) THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;
   PERFORM plugin_finance_counterparty_text(NEW.initial_payload->'reason',1000);
  ELSE
   IF (n-ARRAY['version','latest_revision_id','pending_revision_id','approved_revision_id','updated_at','creator_account','creator_person','creator_binding']) IS DISTINCT FROM(o-ARRAY['version','latest_revision_id','pending_revision_id','approved_revision_id','updated_at','creator_account','creator_person','creator_binding']) OR NEW.version<>OLD.version+1 OR NEW.updated_at IS DISTINCT FROM CURRENT_TIMESTAMP THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;
  END IF;RETURN NEW;
 END IF;
 SELECT * INTO p FROM plugin_finance_counterparty_registry WHERE(tenant_id,legal_entity_id,id)=((n->>'tenant_id')::uuid,(n->>'legal_entity_id')::uuid,(n->>'counterparty_id')::uuid);
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;
 PERFORM plugin_finance_counterparty_lock(p.tenant_id,p.legal_entity_id,p.home_book_id);
 IF TG_TABLE_NAME='plugin_finance_counterparty_revision' THEN
  IF TG_OP='INSERT' THEN
   PERFORM plugin_finance_counterparty_actor(p.tenant_id,p.home_book_id,NEW.maker,ARRAY['OWNER']);
   SELECT * INTO oldrev FROM plugin_finance_counterparty_revision WHERE(tenant_id,legal_entity_id,id)=(p.tenant_id,p.legal_entity_id,p.latest_revision_id);
   SELECT * INTO base FROM plugin_finance_counterparty_revision WHERE(tenant_id,legal_entity_id,id)=(p.tenant_id,p.legal_entity_id,p.approved_revision_id);
   ct=plugin_finance_counterparty_content(NEW.content);
   IF NEW.created_at IS DISTINCT FROM CURRENT_TIMESTAMP OR NEW.version<>1 OR NEW.status<>'PENDING' OR NEW.decision_id IS NOT NULL OR NEW.content IS DISTINCT FROM ct OR p.pending_revision_id IS NOT NULL OR NEW.previous_revision_id IS DISTINCT FROM p.latest_revision_id OR NEW.base_approved_revision_id IS DISTINCT FROM p.approved_revision_id OR NEW.base_approved_digest IS DISTINCT FROM base.content_digest OR NEW.revision_no<>COALESCE(oldrev.revision_no,0)+1 OR base.desired_status='INACTIVE' OR(base.id IS NULL AND NEW.desired_status<>'ACTIVE') OR NEW.content_digest IS DISTINCT FROM plugin_finance_counterparty_revision_digest(NEW.tenant_id,NEW.legal_entity_id,NEW.counterparty_id,NEW.id,NEW.revision_no,NEW.previous_revision_id,NEW.base_approved_revision_id,NEW.base_approved_digest,NEW.desired_status,NEW.content,NEW.reason,NEW.maker) THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;
   IF NEW.revision_no=1 AND(NEW.maker IS DISTINCT FROM p.created_by OR NEW.created_at IS DISTINCT FROM p.created_at OR NEW.content IS DISTINCT FROM p.initial_payload->'content' OR NEW.reason IS DISTINCT FROM p.initial_payload->>'reason') THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;
  ELSE
   IF OLD.status<>'PENDING' OR NEW.version<>2 OR NEW.status='PENDING' OR NEW.decision_id IS NULL OR (n-ARRAY['version','status','decision_id','maker_account','maker_person','maker_binding']) IS DISTINCT FROM(o-ARRAY['version','status','decision_id','maker_account','maker_person','maker_binding']) THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;
  END IF;RETURN NEW;
 END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;
 IF TG_TABLE_NAME='plugin_finance_counterparty_decision' THEN
  SELECT * INTO r FROM plugin_finance_counterparty_revision WHERE(tenant_id,legal_entity_id,id)=(NEW.tenant_id,NEW.legal_entity_id,NEW.revision_id);
  IF r.id IS NULL OR r.counterparty_id<>p.id OR r.status<>'PENDING' OR r.version<>1 OR NEW.content_digest IS DISTINCT FROM r.content_digest OR p.pending_revision_id IS DISTINCT FROM r.id OR NEW.created_at IS DISTINCT FROM CURRENT_TIMESTAMP THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;
  PERFORM plugin_finance_counterparty_actor(p.tenant_id,p.home_book_id,NEW.actor,CASE WHEN NEW.kind='CANCEL' THEN ARRAY['OWNER'] ELSE ARRAY['OWNER','REVIEWER'] END);
  IF NEW.kind='CANCEL' THEN IF NEW.actor->>'accountId' IS DISTINCT FROM r.maker->>'accountId' THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SCOPE_DENIED';END IF;
  ELSE IF NEW.actor->>'personId' IS NOT DISTINCT FROM r.maker->>'personId' THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SELF_APPROVAL_FORBIDDEN';END IF;END IF;
  IF NEW.kind='APPROVE' THEN PERFORM plugin_finance_counterparty_actor(p.tenant_id,p.home_book_id,r.maker,ARRAY['OWNER']);IF r.base_approved_revision_id IS DISTINCT FROM p.approved_revision_id THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_APPROVAL_STALE';END IF;END IF;
 ELSIF TG_TABLE_NAME='plugin_finance_counterparty_audit' THEN
  IF NEW.created_at IS DISTINCT FROM CURRENT_TIMESTAMP THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;
 ELSIF TG_TABLE_NAME='plugin_finance_counterparty_request' THEN
  IF NEW.created_at IS DISTINCT FROM CURRENT_TIMESTAMP THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER finance_counterparty_entity_guard BEFORE UPDATE OR DELETE ON plugin_finance_counterparty_entity_guard FOR EACH ROW EXECUTE FUNCTION plugin_finance_counterparty_guard();
CREATE TRIGGER finance_counterparty_home_guard BEFORE UPDATE OR DELETE ON plugin_finance_counterparty_home_guard FOR EACH ROW EXECUTE FUNCTION plugin_finance_counterparty_guard();
CREATE TRIGGER finance_counterparty_registry_guard BEFORE INSERT OR UPDATE OR DELETE ON plugin_finance_counterparty_registry FOR EACH ROW EXECUTE FUNCTION plugin_finance_counterparty_guard();
CREATE TRIGGER finance_counterparty_revision_guard BEFORE INSERT OR UPDATE OR DELETE ON plugin_finance_counterparty_revision FOR EACH ROW EXECUTE FUNCTION plugin_finance_counterparty_guard();
CREATE TRIGGER finance_counterparty_decision_guard BEFORE INSERT OR UPDATE OR DELETE ON plugin_finance_counterparty_decision FOR EACH ROW EXECUTE FUNCTION plugin_finance_counterparty_guard();
CREATE TRIGGER finance_counterparty_request_guard BEFORE INSERT OR UPDATE OR DELETE ON plugin_finance_counterparty_request FOR EACH ROW EXECUTE FUNCTION plugin_finance_counterparty_guard();
CREATE TRIGGER finance_counterparty_audit_guard BEFORE INSERT OR UPDATE OR DELETE ON plugin_finance_counterparty_audit FOR EACH ROW EXECUTE FUNCTION plugin_finance_counterparty_guard();
CREATE INDEX finance_counterparty_last_approved ON plugin_finance_counterparty_revision(tenant_id,legal_entity_id,counterparty_id,revision_no DESC) WHERE status='APPROVED';
CREATE FUNCTION plugin_finance_counterparty_audit_payload(r plugin_finance_counterparty_revision,d uuid) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$ SELECT jsonb_build_object('revisionId',r.id,'contentDigest',r.content_digest,'content',r.content,'desiredStatus',r.desired_status,'decisionId',d) $$;
CREATE FUNCTION plugin_finance_counterparty_assert(t uuid,e uuid,pid uuid,rid uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql AS $$
DECLARE p plugin_finance_counterparty_registry;r plugin_finance_counterparty_revision;latest plugin_finance_counterparty_revision;approved plugin_finance_counterparty_revision;previous plugin_finance_counterparty_revision;base plugin_finance_counterparty_revision;d plugin_finance_counterparty_decision;pending uuid;expected_version bigint;audits bigint;
BEGIN
 SELECT * INTO p FROM plugin_finance_counterparty_registry WHERE(tenant_id,legal_entity_id,id)=(t,e,pid);IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;
 SELECT * INTO latest FROM plugin_finance_counterparty_revision WHERE(tenant_id,legal_entity_id,counterparty_id)=(t,e,pid) ORDER BY revision_no DESC LIMIT 1;
 SELECT * INTO approved FROM plugin_finance_counterparty_revision WHERE(tenant_id,legal_entity_id,counterparty_id)=(t,e,pid) AND status='APPROVED' ORDER BY revision_no DESC LIMIT 1;
 SELECT id INTO pending FROM plugin_finance_counterparty_revision WHERE(tenant_id,legal_entity_id,counterparty_id)=(t,e,pid) AND status='PENDING';
 expected_version=latest.revision_no*2-CASE WHEN pending IS NULL THEN 0 ELSE 1 END;
 IF latest.id IS NULL OR p.latest_revision_id IS DISTINCT FROM latest.id OR p.pending_revision_id IS DISTINCT FROM pending OR p.approved_revision_id IS DISTINCT FROM approved.id OR p.version IS DISTINCT FROM expected_version OR p.updated_at IS DISTINCT FROM(CASE WHEN latest.status='PENDING' THEN latest.created_at ELSE(SELECT created_at FROM plugin_finance_counterparty_decision WHERE(tenant_id,legal_entity_id,id)=(t,e,latest.decision_id))END) THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;
 IF NOT EXISTS(SELECT 1 FROM plugin_finance_book WHERE tenant_id=t AND id=p.home_book_id AND legal_entity_id=e) THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SCOPE_DENIED';END IF;
 IF rid IS NULL THEN rid=latest.id;END IF;
 SELECT * INTO r FROM plugin_finance_counterparty_revision WHERE(tenant_id,legal_entity_id,id,counterparty_id)=(t,e,rid,pid);
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;
 IF r.content IS DISTINCT FROM plugin_finance_counterparty_content(r.content) OR r.content_digest IS DISTINCT FROM plugin_finance_counterparty_revision_digest(t,e,pid,r.id,r.revision_no,r.previous_revision_id,r.base_approved_revision_id,r.base_approved_digest,r.desired_status,r.content,r.reason,r.maker) THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;
 IF r.revision_no=1 THEN IF r.previous_revision_id IS NOT NULL OR r.base_approved_revision_id IS NOT NULL OR r.desired_status<>'ACTIVE' OR r.maker IS DISTINCT FROM p.created_by OR r.created_at IS DISTINCT FROM p.created_at OR r.content IS DISTINCT FROM p.initial_payload->'content' OR r.reason IS DISTINCT FROM p.initial_payload->>'reason' THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;
 ELSE
  SELECT * INTO previous FROM plugin_finance_counterparty_revision WHERE(tenant_id,legal_entity_id,id)=(t,e,r.previous_revision_id);
  SELECT * INTO base FROM plugin_finance_counterparty_revision WHERE(tenant_id,legal_entity_id,counterparty_id)=(t,e,pid) AND status='APPROVED' AND revision_no<r.revision_no ORDER BY revision_no DESC LIMIT 1;
  IF previous.id IS NULL OR previous.counterparty_id<>pid OR previous.revision_no<>r.revision_no-1 OR previous.status='PENDING' OR previous.created_at>r.created_at OR r.base_approved_revision_id IS DISTINCT FROM base.id OR r.base_approved_digest IS DISTINCT FROM base.content_digest OR base.desired_status='INACTIVE' OR(base.id IS NULL AND r.desired_status<>'ACTIVE') THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;
 END IF;
 SELECT count(*) INTO audits FROM plugin_finance_counterparty_audit WHERE(tenant_id,legal_entity_id,revision_id)=(t,e,r.id);
 IF NOT EXISTS(SELECT 1 FROM plugin_finance_counterparty_audit a WHERE(a.tenant_id,a.legal_entity_id,a.counterparty_id,a.revision_id)=(t,e,pid,r.id) AND a.action='PROPOSE' AND a.actor=r.maker AND a.reason=r.reason AND a.created_at=r.created_at AND a.payload=plugin_finance_counterparty_audit_payload(r,NULL)) THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;
 SELECT * INTO d FROM plugin_finance_counterparty_decision WHERE(tenant_id,legal_entity_id,revision_id)=(t,e,r.id);
 IF r.status='PENDING' THEN IF d.id IS NOT NULL OR r.decision_id IS NOT NULL OR audits<>1 OR r.version<>1 THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;
 ELSE
  IF d.id IS NULL OR r.decision_id IS DISTINCT FROM d.id OR d.counterparty_id<>pid OR d.content_digest IS DISTINCT FROM r.content_digest OR r.status IS DISTINCT FROM(CASE d.kind WHEN 'APPROVE' THEN 'APPROVED' WHEN 'REJECT' THEN 'REJECTED' ELSE 'CANCELLED' END) OR r.version<>2 OR d.created_at<r.created_at OR(d.kind<>'CANCEL' AND d.actor->>'personId' IS NOT DISTINCT FROM r.maker->>'personId') OR(d.kind='CANCEL' AND d.actor->>'accountId' IS DISTINCT FROM r.maker->>'accountId') OR audits<>2 OR NOT EXISTS(SELECT 1 FROM plugin_finance_counterparty_audit a WHERE(a.tenant_id,a.legal_entity_id,a.counterparty_id,a.revision_id)=(t,e,pid,r.id) AND a.action=d.kind AND a.actor=d.actor AND a.reason=d.reason AND a.created_at=d.created_at AND a.payload=plugin_finance_counterparty_audit_payload(r,d.id)) THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;
 END IF;
END $$;
CREATE FUNCTION plugin_finance_counterparty_final() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE n jsonb=to_jsonb(NEW);pid uuid;rid uuid;BEGIN IF TG_TABLE_NAME='plugin_finance_counterparty_registry' THEN pid=NEW.id;ELSE pid=(n->>'counterparty_id')::uuid;END IF;IF TG_TABLE_NAME='plugin_finance_counterparty_revision' THEN rid=NEW.id;ELSIF TG_TABLE_NAME IN('plugin_finance_counterparty_decision','plugin_finance_counterparty_audit','plugin_finance_counterparty_request') THEN rid=(n->>'revision_id')::uuid;END IF;PERFORM plugin_finance_counterparty_assert((n->>'tenant_id')::uuid,(n->>'legal_entity_id')::uuid,pid,rid);RETURN NEW;END $$;
CREATE CONSTRAINT TRIGGER finance_counterparty_registry_final AFTER INSERT OR UPDATE ON plugin_finance_counterparty_registry DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION plugin_finance_counterparty_final();
CREATE CONSTRAINT TRIGGER finance_counterparty_revision_final AFTER INSERT OR UPDATE ON plugin_finance_counterparty_revision DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION plugin_finance_counterparty_final();
CREATE CONSTRAINT TRIGGER finance_counterparty_decision_final AFTER INSERT ON plugin_finance_counterparty_decision DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION plugin_finance_counterparty_final();
CREATE CONSTRAINT TRIGGER finance_counterparty_audit_final AFTER INSERT ON plugin_finance_counterparty_audit DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION plugin_finance_counterparty_final();
CREATE CONSTRAINT TRIGGER finance_counterparty_request_final AFTER INSERT ON plugin_finance_counterparty_request DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION plugin_finance_counterparty_final();
CREATE FUNCTION plugin_finance_counterparty_visible() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE home uuid;BEGIN IF TG_TABLE_NAME='plugin_finance_counterparty_registry' THEN home=NEW.home_book_id;ELSE SELECT home_book_id INTO home FROM plugin_finance_counterparty_registry WHERE(tenant_id,legal_entity_id,id)=(NEW.tenant_id,NEW.legal_entity_id,NEW.counterparty_id);END IF;UPDATE plugin_finance_counterparty_entity_guard SET generation=generation+1 WHERE tenant_id=NEW.tenant_id AND legal_entity_id=NEW.legal_entity_id;UPDATE plugin_finance_counterparty_home_guard SET generation=generation+1 WHERE tenant_id=NEW.tenant_id AND legal_entity_id=NEW.legal_entity_id AND book_id=home;IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_OBSERVATION_UNAVAILABLE';END IF;RETURN NEW;END $$;
CREATE TRIGGER finance_counterparty_registry_visible AFTER INSERT OR UPDATE ON plugin_finance_counterparty_registry FOR EACH ROW EXECUTE FUNCTION plugin_finance_counterparty_visible();
CREATE TRIGGER finance_counterparty_revision_visible AFTER INSERT OR UPDATE ON plugin_finance_counterparty_revision FOR EACH ROW EXECUTE FUNCTION plugin_finance_counterparty_visible();
CREATE TRIGGER finance_counterparty_decision_visible AFTER INSERT ON plugin_finance_counterparty_decision FOR EACH ROW EXECUTE FUNCTION plugin_finance_counterparty_visible();
CREATE FUNCTION plugin_finance_counterparty_command(t uuid,e uuid,b uuid,who jsonb,op text,pid uuid,rid uuid,payload jsonb) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE p plugin_finance_counterparty_registry;r plugin_finance_counterparty_revision;prev plugin_finance_counterparty_revision;base plugin_finance_counterparty_revision;identity jsonb;ct jsonb;initial jsonb;ph text;desired text;why text;dg text;did uuid;n bigint;
BEGIN
 PERFORM plugin_finance_counterparty_fields(payload,CASE op WHEN 'CREATE' THEN ARRAY['schemaVersion','idempotencyKey','reason','operationId','identity','content','organizationDeclarationConfirmed','identityNotPlaceholderConfirmed'] WHEN 'PROPOSE' THEN ARRAY['schemaVersion','idempotencyKey','reason','expectedRegistryVersion','baseApprovedRevisionId','baseApprovedContentDigest','previousRevisionId','desiredStatus','content'] ELSE ARRAY['schemaVersion','idempotencyKey','reason','expectedRegistryVersion','expectedRevisionVersion','contentDigest'] END);
 IF op NOT IN('CREATE','PROPOSE','APPROVE','REJECT','CANCEL') OR payload->>'schemaVersion' IS DISTINCT FROM 'counterparty/1' OR jsonb_typeof(payload->'idempotencyKey') IS DISTINCT FROM 'string' OR length(payload->>'idempotencyKey') NOT BETWEEN 1 AND 128 OR(payload->>'idempotencyKey')~U&'[\0001-\001F\007F-\009F]' THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='INVALID_INPUT';END IF;
 IF octet_length(payload::text)>(CASE WHEN op IN('CREATE','PROPOSE') THEN 16384 ELSE 8192 END) THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_LIMIT_EXCEEDED';END IF;
 PERFORM tenant_id FROM plugin_finance_person_realm WHERE tenant_id=t FOR SHARE;PERFORM pg_advisory_xact_lock(hashtextextended((who->>'accountId')||':'||(payload->>'idempotencyKey'),0));PERFORM plugin_finance_counterparty_lock(t,e,b);
 PERFORM plugin_finance_counterparty_actor(t,b,who,CASE WHEN op IN('APPROVE','REJECT') THEN ARRAY['OWNER','REVIEWER'] ELSE ARRAY['OWNER'] END);
 IF op='CREATE' THEN
  identity=plugin_finance_counterparty_identity(payload->'identity');ct=plugin_finance_counterparty_content(payload->'content');why=plugin_finance_counterparty_text(payload->'reason',1000);
  initial=payload-'idempotencyKey';initial=jsonb_set(jsonb_set(initial,'{identity}',identity),'{content}',ct);ph=plugin_finance_counterparty_digest(initial);
  SELECT * INTO p FROM plugin_finance_counterparty_registry WHERE tenant_id=t AND legal_entity_id=e AND operation_id=(payload->>'operationId')::uuid;
  IF FOUND THEN IF p.home_book_id<>b THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_HOME_SCOPE_REQUIRED';END IF;IF p.initial_payload_hash<>ph THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='IDEMPOTENCY_CONFLICT';END IF;SELECT id INTO rid FROM plugin_finance_counterparty_revision WHERE tenant_id=t AND legal_entity_id=e AND counterparty_id=p.id AND revision_no=1;RETURN jsonb_build_object('counterpartyId',p.id,'revisionId',rid,'newEffect',false);END IF;
  IF EXISTS(SELECT 1 FROM plugin_finance_counterparty_registry WHERE tenant_id=t AND legal_entity_id=e AND namespace=identity->>'namespace' AND jurisdiction=identity->>'jurisdiction' AND identifier=identity->>'identifier') THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_IDENTITY_EXISTS';END IF;
  pid=gen_random_uuid();rid=gen_random_uuid();
  INSERT INTO plugin_finance_counterparty_registry(tenant_id,legal_entity_id,id,home_book_id,namespace,jurisdiction,identifier,operation_id,initial_payload,initial_payload_hash,created_by) VALUES(t,e,pid,b,identity->>'namespace',identity->>'jurisdiction',identity->>'identifier',(payload->>'operationId')::uuid,initial,ph,who);
  n=1;desired='ACTIVE';
 ELSE
  SELECT * INTO p FROM plugin_finance_counterparty_registry WHERE(tenant_id,legal_entity_id,id)=(t,e,pid) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SCOPE_DENIED';END IF;
  IF p.home_book_id<>b THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_HOME_SCOPE_REQUIRED';END IF;
  IF p.version IS DISTINCT FROM(payload->>'expectedRegistryVersion')::bigint THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VERSION_CONFLICT';END IF;
  IF op='PROPOSE' THEN
   SELECT * INTO prev FROM plugin_finance_counterparty_revision WHERE(tenant_id,legal_entity_id,id)=(t,e,p.latest_revision_id);
   SELECT * INTO base FROM plugin_finance_counterparty_revision WHERE(tenant_id,legal_entity_id,id)=(t,e,p.approved_revision_id);
   IF p.pending_revision_id IS NOT NULL OR base.desired_status='INACTIVE' THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;
   IF p.latest_revision_id IS DISTINCT FROM(payload->>'previousRevisionId')::uuid OR p.approved_revision_id IS DISTINCT FROM(payload->>'baseApprovedRevisionId')::uuid OR base.content_digest IS DISTINCT FROM payload->>'baseApprovedContentDigest' THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VERSION_CONFLICT';END IF;
   ct=plugin_finance_counterparty_content(payload->'content');why=plugin_finance_counterparty_text(payload->'reason',1000);desired=payload->>'desiredStatus';IF desired IS NULL OR desired NOT IN('ACTIVE','FROZEN','INACTIVE') OR(base.id IS NULL AND desired<>'ACTIVE') THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;n=prev.revision_no+1;rid=gen_random_uuid();
  ELSIF op IN('APPROVE','REJECT','CANCEL') THEN
   SELECT * INTO r FROM plugin_finance_counterparty_revision WHERE(tenant_id,legal_entity_id,counterparty_id,id)=(t,e,pid,rid) FOR UPDATE;
   IF NOT FOUND OR r.status<>'PENDING' OR p.pending_revision_id IS DISTINCT FROM rid THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='COUNTERPARTY_STATE_CONFLICT';END IF;
   IF r.version IS DISTINCT FROM(payload->>'expectedRevisionVersion')::bigint OR r.content_digest IS DISTINCT FROM payload->>'contentDigest' THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VERSION_CONFLICT';END IF;
   did=gen_random_uuid();why=plugin_finance_counterparty_text(payload->'reason',1000);
   INSERT INTO plugin_finance_counterparty_decision(tenant_id,legal_entity_id,counterparty_id,revision_id,id,kind,content_digest,actor,reason) VALUES(t,e,pid,rid,did,op,r.content_digest,who,why);
   UPDATE plugin_finance_counterparty_revision SET status=CASE op WHEN 'APPROVE' THEN 'APPROVED' WHEN 'REJECT' THEN 'REJECTED' ELSE 'CANCELLED' END,version=2,decision_id=did WHERE(tenant_id,legal_entity_id,id)=(t,e,rid);
   UPDATE plugin_finance_counterparty_registry SET version=version+1,pending_revision_id=NULL,approved_revision_id=CASE WHEN op='APPROVE' THEN rid ELSE approved_revision_id END,updated_at=CURRENT_TIMESTAMP WHERE(tenant_id,legal_entity_id,id)=(t,e,pid);
   SELECT * INTO r FROM plugin_finance_counterparty_revision WHERE(tenant_id,legal_entity_id,id)=(t,e,rid);
   INSERT INTO plugin_finance_counterparty_audit(tenant_id,legal_entity_id,counterparty_id,revision_id,action,actor,reason,payload) VALUES(t,e,pid,rid,op,who,why,plugin_finance_counterparty_audit_payload(r,did));
   RETURN jsonb_build_object('counterpartyId',pid,'revisionId',rid,'newEffect',true);
  ELSE RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='INVALID_INPUT';END IF;
 END IF;
 dg=plugin_finance_counterparty_revision_digest(t,e,pid,rid,n,prev.id,base.id,base.content_digest,desired,ct,why,who);
 INSERT INTO plugin_finance_counterparty_revision(tenant_id,legal_entity_id,counterparty_id,id,revision_no,desired_status,previous_revision_id,base_approved_revision_id,base_approved_digest,content,content_digest,reason,maker) VALUES(t,e,pid,rid,n,desired,prev.id,base.id,base.content_digest,ct,dg,why,who);
 UPDATE plugin_finance_counterparty_registry SET version=version+1,latest_revision_id=rid,pending_revision_id=rid,updated_at=CURRENT_TIMESTAMP WHERE(tenant_id,legal_entity_id,id)=(t,e,pid);
 SELECT * INTO r FROM plugin_finance_counterparty_revision WHERE(tenant_id,legal_entity_id,id)=(t,e,rid);
 INSERT INTO plugin_finance_counterparty_audit(tenant_id,legal_entity_id,counterparty_id,revision_id,action,actor,reason,payload) VALUES(t,e,pid,rid,'PROPOSE',who,why,plugin_finance_counterparty_audit_payload(r,NULL));
 RETURN jsonb_build_object('counterpartyId',pid,'revisionId',rid,'newEffect',true);
END $$;
